// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address attackerAddr) public {
        vm.assume(attackerAddr != address(0));

        HelperCaller helper = new HelperCaller(address(c));

        bool ok1;
        try helper.callAirDrop() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        vm.assume(ok1);

        assertTrue(c._locked() == false);
    }
}

contract HelperCaller {
    ModifierEntrancy immutable target;
    constructor(address _t) { target = ModifierEntrancy(_t); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop() external {
        target.airDrop();
    }
}
